&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de barde&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_barde_0&quot; href=&quot;#Les_arch&#233;types_de_barde_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acad&#233;mie-Des-Grands-Arts-(Barde).html&quot; title=&quot;Royaumes ind&#233;pendants: Acad&#233;mie des Grands arts&quot;&gt;Acad&#233;mie des Grands arts&lt;/a&gt; (CSU)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#194;me-En-Peine-(Barde).html&quot; title=&quot;&#194;me en peine&quot;&gt;&#194;me en peine&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;ologue-(Barde).html&quot; title=&quot;Arch&#233;ologue&quot;&gt;Arch&#233;ologue&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archiviste-(Barde).html&quot; title=&quot;Archiviste&quot;&gt;Archiviste&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Des-Rues-(Barde).html&quot; title=&quot;Artiste des rues&quot;&gt;Artiste des rues&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Masqu&#233;-(Barde).html&quot; title=&quot;Artiste masqu&#233;&quot;&gt;Artiste masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde-De-Cour-(Barde).html&quot; title=&quot;Barde de cour&quot;&gt;Barde de cour&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde-Fun&#232;bre-(Barde).html&quot; title=&quot;Barde fun&#232;bre&quot;&gt;Barde fun&#232;bre&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boucanier-(Barde).html&quot; title=&quot;Boucanier&quot;&gt;Boucanier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casse-Cou-(Barde).html&quot; title=&quot;Casse-cou&quot;&gt;Casse cou&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;C&#233;l&#233;brit&#233;-(Barde).html&quot; title=&quot;C&#233;l&#233;brit&#233;&quot;&gt;C&#233;l&#233;brit&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chantemer-(Barde).html&quot; title=&quot;Chantemer&quot;&gt;Chantemer&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-De-Leau-(Barde).html&quot; title=&quot;Chanteur de l’eau&quot;&gt;Chanteur de l&#39;eau&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danseur-Des-Flammes-(Barde).html&quot; title=&quot;Danseur des flammes&quot;&gt;Danseur des flammes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;magogue-(Barde).html&quot; title=&quot;D&#233;magogue&quot;&gt;D&#233;magogue&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Derviche-(Barde).html&quot; title=&quot;Derviche&quot;&gt;Derviche&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Derviche-De-La-Fleur-De-Laube-(Barde).html&quot; title=&quot;Derviche de l&amp;#39;aube (barde)&quot;&gt;Derviche de l&#39;aube&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tective-(Barde).html&quot; title=&quot;D&#233;tective&quot;&gt;D&#233;tective&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diva-Ch&#233;liaxienne-(Barde).html&quot; title=&quot;Diva&quot;&gt;Diva&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Jappeur-(Barde).html&quot; title=&quot;Dragon jappeur&quot;&gt;Dragon jappeur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duelliste-Des-Arcanes-(Barde).html&quot; title=&quot;Duelliste des arcanes&quot;&gt;Duelliste des arcanes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Farceur-(Barde).html&quot; title=&quot;Farceur&quot;&gt;Farceur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappeson-(Barde).html&quot; title=&quot;Frappeson&quot;&gt;Frappeson&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Geisha-(Barde).html&quot; title=&quot;Geisha&quot;&gt;Geisha&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Intellectuel-(Barde).html&quot; title=&quot;Intellectuel&quot;&gt;Intellectuel&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interpr&#232;te-De-Ballades-Argent&#233;es-(Barde).html&quot; title=&quot;Interpr&#232;te de ballades argent&#233;es&quot;&gt;Interpr&#232;te de ballades argent&#233;es&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchand-De-Sable-(Barde).html&quot; title=&quot;Marchand de sable&quot;&gt;Marchand de sable&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marionnettiste-Des-Ombres-(Barde).html&quot; title=&quot;Marionnettiste des ombres&quot;&gt;Marionnettiste des ombres&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Wayang-(Race).html&quot; title=&quot;Les wayangs&quot;&gt;Wayang&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Meneur-(Barde).html&quot; title=&quot;Meneur&quot;&gt;Meneur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Inflexible-(Barde).html&quot; title=&quot;Messager inflexible&quot;&gt;Messager inflexible&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orateur-Animal-(Barde).html&quot; title=&quot;Orateur animal&quot;&gt;Orateur animal&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phr&#233;nologue-(Barde).html&quot; title=&quot;Phr&#233;nologue&quot;&gt;Phr&#233;nologue&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitateur-(Barde).html&quot; title=&quot;Prestidigitateur&quot;&gt;Prestidigitateur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scalde-Sauvage-(Barde).html&quot; title=&quot;Scalde sauvage&quot;&gt;Scalde sauvage&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soignechant-(Barde).html&quot; title=&quot;Soignechant&quot;&gt;Soignechant&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voix-De-La-Nature-(Barde).html&quot; title=&quot;Voix de la nature&quot;&gt;Voix de la nature&lt;/a&gt; (MCA)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le chantemer est chez lui sur les eaux bleues de l’oc&#233;an. Il rend les aliz&#233;s favorables et est tr&#232;s pris&#233; des capitaines de navire souhaitant attirer la chance sur leurs bateaux et leurs &#233;quipages.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Repr&#233;sentation bardique.&lt;a class=&quot;headeranchor&quot; id=&quot;Repr&#233;sentation_bardique_0&quot; href=&quot;#Repr&#233;sentation_bardique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;
Un chantemer ma&#238;trise les types de &lt;a class=&quot;pagelink&quot; href=&quot;Barde#Representationbardique.html&quot; title=&quot;repr&#233;sentation bardique&quot;&gt;repr&#233;sentation bardique&lt;/a&gt; suivants.&lt;br /&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Chanson de marin (Sur).&lt;/i&gt; Un chantemer apprend &#224; lutter contre le mal de mer et l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puisement&lt;/a&gt; des longs voyages en bateau. Lorsqu’il d&#233;cide d’utiliser cette aptitude, il effectue un test de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; &#224; chaque round. Tous les alli&#233;s situ&#233;s dans un rayon de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) (dont le barde) peuvent utiliser le r&#233;sultat de son test en lieu et place de leur propre &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; contre l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puisement&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.-La-Fatigue-Se-Dissipe-Au-Bout-De-Huit-Heures-De-Repos-Total.-Un-Personnage-Fatigu&#233;-Devient-&#201;puis&#233;-D&#232;s-Qu’Il-Fait-Quoi-Que-Ce-Soit-Qui-Causerait-Un-Nouvel-&#201;tat-Fatigu&#233;..html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigue&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Naus&#233;eux.html&quot; title=&quot;Naus&#233;eux&quot;&gt;naus&#233;e&lt;/a&gt; ou la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#232;vre&lt;/a&gt;. S’ils sont d&#233;j&#224; affect&#233;s par l’un de ces &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;tats pr&#233;judiciables&lt;/a&gt;, un nouveau jet leur est accord&#233; &#224; chaque round de la chanson de marin, avec comme base le r&#233;sultat du test de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; du barde. Une chanson de marin n’a aucune influence sur les effets instantan&#233;s ou ceux qui n’autorisent pas de sauvegarde. Cette aptitude utilise une composante sonore et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#CONTRECHANT&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;contrechant&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Mer calme (Sur).&lt;/i&gt; Au niveau 3, un chantemer peut calmer des eaux agit&#233;es dans un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Rayon.html&quot; title=&quot;rayon&quot;&gt;rayon&lt;/a&gt; de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) autour de lui et r&#233;duit d’un nombre &#233;gal &#224; son niveau de barde le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (marin) et de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;, ainsi que les tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; effectu&#233;s &#224; bord d’un navire (minimum 10), et ce tant qu’il poursuit sa repr&#233;sentation. Il peut prolonger cette dur&#233;e &#224; une heure en jouant pendant 10 rounds cons&#233;cutifs. Cette aptitude utilise une composante sonore et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#INSPIRATIONTALENTUEUSE&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;inspiration talentueuse&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Siffler le vent (Sur).&lt;/i&gt; &#192; partir du niveau 6, un chantemer peut cr&#233;er une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bourrasque.html&quot; title=&quot;Bourrasque&quot;&gt;bourrasque&lt;/a&gt;&lt;/i&gt; qui dure tant qu’il continue sa repr&#233;sentation. Il peut prolonger cette dur&#233;e &#224; une minute en jouant pendant 5 rounds cons&#233;cutifs. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#SUGGESTION&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;suggestion&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Appeler la temp&#234;te (Sur).&lt;/i&gt; Au niveau 18, un chantemer peut imiter les effets des sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-De-Leau.html&quot; title=&quot;Contr&#244;le de l&amp;#39;eau&quot;&gt;contr&#244;le de l’eau&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Du-Climat.html&quot; title=&quot;Contr&#244;le du climat&quot;&gt;contr&#244;le du climat&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Vents.html&quot; title=&quot;Contr&#244;le des vents&quot;&gt;contr&#244;le des vents&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp&#234;te-Vengeresse.html&quot; title=&quot;Temp&#234;te vengeresse&quot;&gt;temp&#234;te vengeresse&lt;/a&gt;&lt;/i&gt;. Il utilisera son niveau de barde comme &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; et devra mener sans discontinuer sa repr&#233;sentation pendant 1 round par &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau de sort&lt;/a&gt;, comme s&#39;il &#233;tait un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt;. Les effets continuent aussi longtemps que le barde poursuit sa performance (les effet de contr&#244;le du climat ont lieu imm&#233;diatement), mais pas plus longtemps que la dur&#233;e normale du sort. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#suggestion_de_groupe&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;suggestion de groupe&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Globe trotteur (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Globe_trotteur_Ext_1&quot; href=&quot;#Globe_trotteur_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un chantemer gagne un bonus &#233;gal &#224; la moiti&#233; de son niveau de barde sur les tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local), &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) et &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt;. Il peut relancer le test d’une des comp&#233;tences &#233;num&#233;r&#233;es ci-dessus, mais doit garder le second r&#233;sultat, et ce m&#234;me s’il est plus mauvais. Il pourra relancer un test de plus une fois au niveau 5, puis une fois de plus par tranche de cinq niveaux au-del&#224;. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#SAVOIRBARDIQUE&quot; title=&quot;Le barde&quot;&gt;savoir bardique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Familier&lt;a class=&quot;headeranchor&quot; id=&quot;Familier_2&quot; href=&quot;#Familier_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, un chantemer acquiert un animal de compagnie exotique – un singe ou un perroquet (consid&#233;rez qu’il est &#233;quivalent &#224; un corbeau). Le niveau du barde servira de niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; pour d&#233;terminer les caract&#233;ristiques du &lt;a class=&quot;pagelink&quot; href=&quot;Familiers.html&quot; title=&quot;familier&quot;&gt;familier&lt;/a&gt;. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#versatilit&#233;_artistique&quot; title=&quot;Le barde&quot;&gt;versatilit&#233; artistique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pied marin (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pied_marin_Ext_3&quot; href=&quot;#Pied_marin_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, un chantemer b&#233;n&#233;ficie d’un bonus de +4 sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets du vent et de l’eau, ainsi que contre les effets qui pourraient le faire glisser, chuter ou tomber &#224; terre. Il b&#233;n&#233;ficie d’un +2 &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre la &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;, le &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Renversement.html&quot; title=&quot;renversement&quot;&gt;renversement&lt;/a&gt; et le &lt;a class=&quot;pagelink&quot; href=&quot;Croc-En-Jambe.html&quot; title=&quot;croc-en-jambe&quot;&gt;croc-en-jambe&lt;/a&gt;. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#&#233;rudition&quot; title=&quot;Le barde&quot;&gt;&#233;rudition&lt;/a&gt;.
